head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "1",
        "custom": "19941005",
        "col2": "1"
    }, {
        "col1": "1",
        "custom": "v3",
        "col2": "1"
    }, {
        "col1": "1",
        "custom": "v1",
        "col2": "1"
    }];
    dataList1.setJSON(jsonData);
    var jsonData1 = [{
        "col1": "v1",
        "col2": "lb1"
    }, {
        "col1": "v2",
        "col2": "lb2"
    }, {
        "col1": "v3",
        "col2": "lb3"
    }];
    dataList2.setJSON(jsonData1);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    ++sIdx;
    select1.addItem("value" + sIdx, "label" + sIdx);
};
scwin.fn1 = function() {
    gridView1.setCellInputType(0, "custom", {
        inputType: "calendar",
        options: {
            imageSrc: "",
            viewType: "icon"
        }
    });
}
scwin.trigger3_onclick = function(e) {
    scwin.fn1();
};
scwin.__hasClass = function() {
    var classList = scwin.__getDom('G_'+$p.id+'gridView1__dynamic_calendar_0_1').className;
    return classList.indexOf('gridBodyDefault') == -1;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.sIdx = 0;
}
